<parameter>contents">class RateLimiter {
  constructor() {
    this.attempts = new Map();
    this.lockoutDuration = 15 * 60 * 1000; // 15 minutes
    this.maxAttempts = 5;
    this.resetWindow = 10 * 60 * 1000; // 10 minutes
  }

  isLocked(email) {
    const record = this.attempts.get(email);
    if (!record) return false;

    const now = Date.now();
    if (now - record.lastAttempt > this.lockoutDuration) {
      this.attempts.delete(email);
      return false;
    }

    return record.locked;
  }

  recordFailure(email) {
    const now = Date.now();
    const record = this.attempts.get(email) || {
      count: 0,
      firstAttempt: now,
      lastAttempt: now,
      locked: false
    };

    record.lastAttempt = now;

    if (now - record.firstAttempt > this.resetWindow) {
      record.count = 1;
      record.firstAttempt = now;
    } else {
      record.count++;
    }

    if (record.count >= this.maxAttempts) {
      record.locked = true;
    }

    this.attempts.set(email, record);
    return { locked: record.locked, attempts: record.count, maxAttempts: this.maxAttempts };
  }

  recordSuccess(email) {
    this.attempts.delete(email);
  }

  getRemainingTime(email) {
    const record = this.attempts.get(email);
    if (!record || !record.locked) return null;

    const timeLeft = this.lockoutDuration - (Date.now() - record.lastAttempt);
    return Math.ceil(timeLeft / 1000);
  }
}

export default new RateLimiter();
