<parameter>contents">import express from 'express';
import session from 'express-session';
import bodyParser from 'body-parser';
import cors from 'cors';
import User from './user.js';
import rateLimiter from './rateLimiter.js';

const app = express();
const PORT = 3000;

app.use(cors());
app.use(bodyParser.json());

app.use(session({
  secret: 'your-secret-key-change-in-production',
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: false, // set true in production with HTTPS
    maxAge: 24 * 60 * 60 * 1000, // 24 hours
    httpOnly: true
  }
}));

// Validation helper
function validateEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function validatePassword(password) {
  return password.length >= 8;
}

// Routes

app.post('/signup', async (req, res) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password required' });
  }

  if (!validateEmail(email)) {
    return res.status(400).json({ error: 'Invalid email format' });
  }

  if (!validatePassword(password)) {
    return res.status(400).json({ error: 'Password must be at least 8 characters' });
  }

  try {
    const user = await User.create(email, password);
    req.session.userId = user.id;
    req.session.email = user.email;

    res.status(201).json({
      success: true,
      message: 'Account created successfully',
      user: { id: user.id, email: user.email }
    });
  } catch (error) {
    res.status(409).json({ error: error.message });
  }
});

app.post('/login', async (req, res) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password required' });
  }

  if (rateLimiter.isLocked(email)) {
    const secondsLeft = rateLimiter.getRemainingTime(email);
    return res.status(429).json({
      error: 'Too many failed attempts. Try again later.',
      retryAfter: secondsLeft
    });
  }

  try {
    const user = await User.findByEmail(email);
    if (!user) {
      rateLimiter.recordFailure(email);
      return res.status(401).json({ error: 'Invalid email or password' });
    }

    const isValid = await User.verifyPassword(email, password);
    if (!isValid) {
      const result = rateLimiter.recordFailure(email);
      return res.status(401).json({
        error: 'Invalid email or password',
        attemptsRemaining: result.maxAttempts - result.attempts,
        locked: result.locked
      });
    }

    rateLimiter.recordSuccess(email);
    req.session.userId = user.id;
    req.session.email = user.email;

    res.json({
      success: true,
      message: 'Logged in successfully',
      user: { id: user.id, email: user.email }
    });
  } catch (error) {
    res.status(500).json({ error: 'Server error' });
  }
});

app.post('/logout', (req, res) => {
  req.session.destroy((err) => {
    if (err) {
      return res.status(500).json({ error: 'Could not log out' });
    }
    res.json({ success: true, message: 'Logged out successfully' });
  });
});

app.get('/me', (req, res) => {
  if (!req.session.userId) {
    return res.status(401).json({ error: 'Not authenticated' });
  }

  res.json({
    user: {
      id: req.session.userId,
      email: req.session.email
    }
  });
});

app.listen(PORT, () => {
  console.log(`Auth server running on http://localhost:${PORT}`);
  console.log('\nEndpoints:');
  console.log('POST /signup - Register new user');
  console.log('POST /login - Login user');
  console.log('POST /logout - Logout user');
  console.log('GET /me - Get current user');
});
